"""The published site must be generated by the real engine, not a mock."""

from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def test_landing_pages_are_up_to_date() -> None:
    result = subprocess.run(
        [sys.executable, str(ROOT / "scripts" / "build_site.py"), "--check"],
        cwd=ROOT,
        capture_output=True,
    )
    assert result.returncode == 0, result.stderr.decode("utf-8", "replace")


def test_landing_page_has_no_second_renderer() -> None:
    index = (ROOT / "docs" / "index.html").read_text(encoding="utf-8")
    assert "function render(md)" not in index
    assert "demoMd" not in index
    assert 'class="real-frame"' in index


def test_comparison_page_renders_unchecked_task_as_unchecked() -> None:
    compare = (ROOT / "docs" / "compare.html").read_text(encoding="utf-8")
    match = re.search(r"<input[^>]*>\s*Take over the world", compare)
    assert match is not None
    assert "checked" not in match.group(0)
    assert "✓ Take over the world" not in compare
